import { QbsTable } from 'qbs-react-grid'
import { useEffect, useState } from 'react'

import { TableColumns } from '../../common/types'
import InfoBox from '../../components/app/alertBox/infoBox'
import ResetPassword from '../../components/app/resetPassword'
import { DialogModal, TextField } from '../../components/common'
import Icons from '../../components/common/icons'
import ListingHeader from '../../components/common/ListingTiles'
import { useSnackbarManager } from '../../components/common/snackbar'
import { checkPermissions } from '../../layout/store'
import { useAdminUserFilterStore } from '../../store/filterSore/adminUserStore'
// import { calcWindowHeight } from '../../utilities/calcHeight'
import { getSortedColumnName } from '../../utilities/parsers'
import { useQueryClient } from '@tanstack/react-query'
// import { handleReturnEmptyMsg } from '../../utilities/validation'
import {
  deActivateAdmin,
  getAdminDetails,
  sendAdminInvitation,
  // useAdminUser,
  DISABLE_NONLOGIN_APIS,
  usePlans,
  deletePlan,
} from './api'
import { getColumns } from './columns'
import CreatePlan from './create'
import { useNavigate } from 'react-router-dom'

export default function Plans() {
  const [columns, setColumns] = useState<TableColumns[]>([])
  const { enqueueSnackbar } = useSnackbarManager()
  const [deleteItem] = useState('')
  const [status] = useState('')
  const [deleteModal, setDeleteModal] = useState(false)
  const [createOpen, setCreateOpen] = useState(false)
  const [viewMode, setViewMode] = useState(false)
  const [edit, setEdit] = useState(false)
  const [rowData, setRowData] = useState<any>()
  const [changePassword, setChangePassword] = useState(false)
  const [userName, setUserName] = useState('')
  const [userId, setUserId] = useState('')
  const [openConfirm, setOpenConfirm] = useState(false)

  const [editViewIndicator, setEditViewIndicator] = useState(false)
  const [viewIndicator, setViewIndicator] = useState(false)
  const [loader, setloader] = useState(false)
  const navigate = useNavigate()

  const { pageParams, setPageParams, selectedRows, setSelectedRows } =
    useAdminUserFilterStore()
  // const { page, per_page, search, ordering, filters } = pageParams
  // const searchParams = {
  //   page: page,
  //   per_page: per_page,
  //   search: search,
  //   ordering: ordering,
  //   ...filters,
  // }

  const { page, per_page, search, ordering } = pageParams
  const searchParams = {
    page,
    per_page: Number(per_page ?? 10),
    search,
    ordering,
    // limit: Number(per_page ?? 10),
  }

  const handleEditPlan = (row: any) => {
    // Open drawer in edit mode with row data
    setRowData({ plan: row })
    setEdit(true)
    setViewMode(false)
    setCreateOpen(true)
  }

  const handleDeletePlan = async (row: any) => {
    try {
      await deletePlan(row?.id)
      enqueueSnackbar('Plan deleted successfully', { variant: 'success' })
      queryClient.invalidateQueries(['plans_list'])
    } catch (err: any) {
      enqueueSnackbar(err?.response?.data?.message || 'Failed to delete plan', {
        variant: 'error',
      })
    }
  }
  const { data, isFetching } = usePlans(searchParams)
  const queryClient = useQueryClient()
  // Clamp page to valid range when meta changes
  useEffect(() => {
    const totalPages = data?.meta?.total_pages
    if (typeof totalPages === 'number' && totalPages > 0) {
      if ((pageParams?.page ?? 1) > totalPages) {
        setPageParams({ ...pageParams, page: totalPages })
      } else if ((pageParams?.page ?? 1) < 1) {
        setPageParams({ ...pageParams, page: 1 })
      }
    } else if ((pageParams?.page ?? 1) < 1) {
      setPageParams({ ...pageParams, page: 1 })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [data?.meta?.total_pages])
  const onChangePage = (pageNumber: number) => {
    // Use 1-based page numbers consistently with QbsTable and API
    setPageParams({
      ...pageParams,
      page: pageNumber,
    })
  }
  const onChangeRowsPerPage = (count: number | string) => {
    setPageParams({
      ...pageParams,
      per_page: Number(count),
      page: 1,
    })
  }
  const onViewAction = async (row: any) => {
    setViewIndicator(true)
    if (row?.user?.id) {
      const data = await getAdminDetails(row?.user?.id)
      setRowData(data)
      setViewMode(true)
      setCreateOpen(true)
    }
  }
  useEffect(() => {
    setColumns(
      getColumns((row: any) => {
        navigate(`/plans/${row?.id}`)
      })
    )
  }, [])

  const handleSeach = (key?: string) => {
    setPageParams({
      ...pageParams,
      search: key as string,
      page: 1,
    })
  }

  // const handleDeleteModel = (id: string, username: string, status: string) => {
  //   setDeleteItem(id)
  //   setDeleteModal(true)
  //   setUserName(username)
  //   setStatus(status)
  // }

  const handleSendInvitation = () => {
    setloader(true)
    sendAdminInvitation(deleteItem ?? '')
      .then((res) => {
        enqueueSnackbar(
          res.message ? res.message : 'Invitation Send Successfully',
          {
            variant: 'success',
          }
        )
        setloader(false)
        // refetch()
        setOpenConfirm(false)

        setSelectedRows(
          selectedRows?.filter((sel: any) => sel !== deleteItem) || []
        )
      })
      .catch((err: any) => {
        setloader(false)
        enqueueSnackbar(
          err?.response?.data?.error?.message || err?.response?.data?.message,
          { variant: 'error' }
        )
      })
  }

  const handleDeleteAdmin = () => {
    setloader(true)
    deActivateAdmin(deleteItem)
      .then(() => {
        enqueueSnackbar('Status Updated successfully', {
          variant: 'success',
        })
        setloader(false)
        // refetch()
        setSelectedRows(
          selectedRows?.filter((sel: string | number) => sel !== deleteItem) ||
            []
        )
        setDeleteModal(false)
      })
      .catch((err) => {
        setloader(false)
        enqueueSnackbar(
          err?.response?.data?.error?.message || err?.response?.data?.message,
          { variant: 'error' }
        )
      })
  }
  // const handleEdit = async (rowData: any) => {
  //   if (rowData?.user?.id) {
  //     const data = await getAdminDetails(rowData?.user?.id)
  //     setRowData(data)
  //     setCreateOpen(true)
  //     setViewMode(false)
  //     setEdit(true)
  //   }
  // }
  // const handleAction = () => {
  //   setCreateOpen(true)
  //   setRowData({})
  //   setEdit(false)
  //   setViewMode(false)
  // }
  const handleClose = () => {
    setCreateOpen(false)
    setViewMode(false)
    setEdit(false)
    if (viewIndicator && editViewIndicator) {
      setViewIndicator(false)
      setEditViewIndicator(false)
      onViewAction(rowData)
    }
  }

  const handleRefresh = () => {
    // refetch()
  }
  const basicData = {
    title: 'Plans',
    icon: 'user',
  }
  const openDrawer = () => {
    setCreateOpen(true)
    setRowData({})
  }
  const headerProps = {
    actionTitle: 'Create Plan',
  }
  const handleSort = (orderColumn: any, orderDirection: any) => {
    setPageParams({
      ...pageParams,
      sortColumn: orderColumn,
      sortType: orderDirection,
      ordering: getSortedColumnName(orderColumn, orderDirection),
    })
  }
  // const handleResetPassword = (userId: string, username: string) => {
  //   setChangePassword(true)
  //   setUserId(userId)
  //   setUserName(username)
  // }
  // const handleOpenInvitation = (id: any) => {
  //   setDeleteItem(id)
  //   setOpenConfirm(true)
  // }
  return (
    <div>
      {DISABLE_NONLOGIN_APIS ? (
        <div className="p-6">
          <InfoBox content={'This section is disabled for this build.'} />
        </div>
      ) : (
        <>
          <ListingHeader
            data={basicData}
            onActionClick={openDrawer}
            actionProps={headerProps}
            checkPermission={checkPermissions('Employee', 'create')}
          />
          {/* <PageTitle data={data?.total} isLoading={isFetching} /> */}
          <div className=" p-4">
            <QbsTable
              data={data?.plans ?? []}
              dataRowKey="id"
              toolbar={true}
              search={true}
              isLoading={isFetching}
              sortType={pageParams.sortType}
              sortColumn={pageParams.sortColumn}
              handleColumnSort={handleSort}
              emptyTitle="No records to display"
              // emptySubTitle={handleReturnEmptyMsg(search)}
              columns={columns}
              pagination={true}
              renderSortIcon={(sortType?: 'asc' | 'desc' | undefined) => {
                return sortType === 'asc' ? (
                  <Icons name="ascending-icon" />
                ) : sortType === 'desc' ? (
                  <Icons name="descending-icon" />
                ) : (
                  <Icons name="qbs-sort-icon" />
                )
              }}
              paginationProps={{
                onPagination: onChangePage,
                total: data?.meta?.total_count ?? 0,
                currentPage:
                  typeof data?.meta?.current_page === 'number'
                    ? (data?.meta?.current_page as number)
                    : (pageParams?.page ?? 1),
                rowsPerPage: Number(
                  pageParams?.per_page ?? data?.meta?.per_page ?? 10
                ),
                onRowsPerPage: onChangeRowsPerPage,
                dropOptions: [10, 20, 30, 50, 100],
              }}
              actionProps={[
                {
                  icon: <Icons name="eye" />,
                  action: (row: any) => navigate(`/plans/${row?.id}`),
                  title: 'view',
                  toolTip: 'View',
                },

                {
                  icon: <Icons name="edit" />,
                  action: (row: any) => handleEditPlan(row),
                  title: 'edit',
                  toolTip: 'Edit',
                },
                {
                  icon: <Icons name="delete" />,
                  action: (row: any) => handleDeletePlan(row),
                  title: 'delete',
                  toolTip: 'Delete',
                },
              ]}
              searchValue={pageParams?.search}
              onSearch={handleSeach}
              asyncSearch
              handleSearchValue={(key?: string) => handleSeach(key)}
              columnToggle
              //       className="bg-primary"
              //     />
              //   </div>
              // }
            />
          </div>

          <DialogModal
            isOpen={deleteModal}
            onClose={() => setDeleteModal(false)}
            // title={'Delete Admin User'}
            title={
              status == 'Active'
                ? 'Deactivate Admin User'
                : 'Activate Admin User'
            }
            onSubmit={() => handleDeleteAdmin()}
            secondaryAction={() => setDeleteModal(false)}
            secondaryActionLabel="Cancel"
            actionLabel={status == 'Active' ? 'Deactivate' : 'Activate'}
            actionLoader={loader}
            className="z-50"
            body={
              <>
                {/* <InfoBox content={'Are you sure to delete this admin user ?'} /> */}
                <p className="pb-4">
                  {status == 'Active'
                    ? 'Are you sure to deactivate this admin user ?'
                    : 'Are you sure to activate this admin user ?'}
                </p>
                <div className="flex flex-col gap-4">
                  <div className="w-full flex flex-col gap-2">
                    <TextField
                      id="1"
                      name="email"
                      value={userName ?? ''}
                      disabled={true}
                      label={'Admin Email id'}
                    />
                  </div>
                </div>
              </>
            }
          />
          <ResetPassword
            changePassword={changePassword}
            setChangePassword={setChangePassword}
            userId={userId}
            setUserId={setUserId}
            from={'Admin'}
            userName={userName}
            setUserName={setUserName}
          />

          <CreatePlan
            isDrawerOpen={createOpen}
            rowData={rowData}
            edit={edit}
            setViewMode={setViewMode}
            setEdit={setEdit}
            viewMode={viewMode}
            handleClose={handleClose}
            handleRefresh={handleRefresh}
          />
          <DialogModal
            isOpen={openConfirm}
            onClose={() => setOpenConfirm(false)}
            title={'Send Invitation'}
            onSubmit={() => handleSendInvitation()}
            secondaryAction={() => setOpenConfirm(false)}
            secondaryActionLabel="Cancel"
            actionLabel="Send"
            actionLoader={loader}
            body={
              <InfoBox
                content={'Are you sure you want to send the invitation?'}
              />
            }
          />
        </>
      )}
    </div>
  )
}
